'use strict';
const uid=()=>globalThis.crypto?.randomUUID?.()||'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const $=id=>document.getElementById(id),KEY='central-bank-wallet-v2',RATE=95,MAX=1e12;
const market=[{id:'global',name:'Global Equity',symbol:'GE',price:25000,currency:'rub',category:'Фонд акций'},{id:'bonds',name:'Stable Bonds',symbol:'SB',price:10000,currency:'rub',category:'Облигационный фонд'},{id:'gold',name:'Gold Reserve',symbol:'AU',price:9500,currency:'rub',category:'Золото'}];
const defaults=()=>({rub:125000000,usd:2500000,history:[],deposits:[{id:'deposit-initial',name:'Капитал Плюс',amount:20000000,rate:16,months:12,opened:Date.now()}],holdings:{global:320,bonds:500,gold:200},assets:[{id:'home',name:'Апартаменты · Москва',type:'Недвижимость',value:85000000},{id:'auto',name:'Mercedes-Benz S-Class',type:'Автомобиль',value:18000000}],loans:[{id:'loan-initial',name:'Персональный кредит',balance:1500000,rate:18,months:36}],policies:[{id:'policy-initial',name:'Защита дома',premium:25000,coverage:85000000}],frozen:{rub:false,usd:false},limits:{rub:500000,usd:10000},hidden:false,notifications:true,goal:500000000});
let state=defaults(),mode='',params={},toastTimer,route='overview';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&['rub','usd'].every(c=>Number.isFinite(saved[c])&&saved[c]>=0&&saved[c]<=MAX)){state={...state,...saved};for(const k of ['deposits','assets','loans','policies','history'])if(!Array.isArray(state[k]))state[k]=defaults()[k]}}catch{}
if(!localStorage.getItem(KEY)){try{const old=JSON.parse(localStorage.getItem('central-bank-demo-v1'));if(old&&['rub','usd'].every(c=>Number.isFinite(old[c])&&old[c]>=0&&old[c]<=MAX)){state.rub=old.rub;state.usd=old.usd}}catch{}}
const fmt=(n,c='rub')=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:c==='usd'?'USD':'RUB',minimumFractionDigits:0,maximumFractionDigits:2}).format(n),money=(n,c='rub')=>state.hidden?'••• •••':fmt(n,c),round=n=>Math.round(n*100)/100;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const investmentTotal=()=>market.reduce((sum,m)=>sum+(state.holdings[m.id]||0)*m.price,0),depositTotal=()=>state.deposits.reduce((n,d)=>n+d.amount,0),propertyTotal=()=>state.assets.reduce((n,a)=>n+a.value,0),debtTotal=()=>state.loans.reduce((n,l)=>n+l.balance,0),liquid=()=>state.rub+state.usd*RATE,net=()=>liquid()+depositTotal()+investmentTotal()+propertyTotal()-debtTotal();
function notify(t){if(!state.notifications)return;$('toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{$('toast').textContent='Не удалось сохранить данные в браузере.'}render()}
function record(title,amount,currency='rub',category='transfer',direction='out'){state.history.unshift({id:uid(),title,amount,currency,category,direction,date:Date.now()});state.history=state.history.slice(0,300)}
const btn=(text,action,extra='',cls='')=>`<button type="button" class="service-btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const facts=items=>`<ul class="fact-list">${items.map(([l,v])=>`<li><span>${l}</span><span>${v}</span></li>`).join('')}</ul>`;
const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
function txHtml(tx){return `<div class="transaction"><div class="tx-icon">${tx.direction==='in'?'↓':tx.category==='exchange'?'⇄':'↑'}</div><div><div class="tx-name">${esc(tx.title)}</div><div class="tx-date">${new Date(tx.date).toLocaleDateString('ru-RU')} · ${new Date(tx.date).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</div></div><div class="tx-amount ${tx.direction==='out'?'outgoing':''}">${state.hidden?'•••':(tx.direction==='in'?'+':'−')+fmt(tx.amount,tx.currency)}</div></div>`}
function historyHtml(items){return items.length?items.map(txHtml).join(''):'<div class="empty-state">Операций пока нет</div>'}
const icon=(symbol)=>`<div class="product-icon">${symbol}</div>`;
function renderOverview(){ $('total').textContent=money(liquid());$('rubBalance').textContent=money(state.rub);$('usdBalance').textContent=money(state.usd,'usd');$('visibility').setAttribute('aria-pressed',String(state.hidden));$('visibility').setAttribute('aria-label',state.hidden?'Показать балансы':'Скрыть балансы');$('transactions').innerHTML=historyHtml(state.history.slice(0,3));$('txCount').textContent=state.history.length?`${state.history.length} оп.`:'';
if(!$('overviewSummary')){$('legacyOverview').insertAdjacentHTML('beforeend','<div class="section-heading"><h2>Мой капитал</h2><a class="text-button" href="#assets">Все активы →</a></div><div class="grid-3" id="overviewSummary"></div><div class="quick-services"><a class="quick-service" href="#deposits"><span>◷</span>Вклады и накопления</a><a class="quick-service" href="#investments"><span>↗</span>Инвестиции</a><a class="quick-service" href="#loans"><span>◴</span>Кредиты</a><a class="quick-service" href="#insurance"><span>✓</span>Страхование</a></div>')}
$('overviewSummary').innerHTML=`<article class="product"><span class="caption">На вкладах</span><strong class="value">${money(depositTotal())}</strong><a href="#deposits" class="text-button">Управлять вкладами →</a></article><article class="product"><span class="caption">Инвестиционный портфель</span><strong class="value">${money(investmentTotal())}</strong><a href="#investments" class="text-button">Открыть портфель →</a></article><article class="product"><span class="caption">Чистые активы</span><strong class="value">${money(net())}</strong><a href="#assets" class="text-button">Структура капитала →</a></article>`}
function accounts(){const cards=document.querySelector('#cards .cards').cloneNode(true);cards.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));return heading('Счета и карты','Два счёта. Один личный Wallet.')+`<div class="cards">${['rub','usd'].map((c,i)=>`<div>${cards.children[i].outerHTML}<div class="account-extra"><div class="account-state ${state.frozen[c]?'frozen':''}">${state.frozen[c]?'Карта заморожена':'Карта активна'} · ${c==='rub'?'Mastercard':'Visa'}</div><div class="row">${btn(state.frozen[c]?'Разморозить':'Заморозить','freeze',`data-currency="${c}"`)}${btn('Лимиты','limit',`data-currency="${c}"`)}<span class="caption">${money(state.limits[c],c)} / день</span></div></div></div>`).join('')}</div><div class="grid-2 gap"><article class="product"><h2>Рублёвый счёт</h2>${facts([['Доступно',money(state.rub)],['Валюта','Российский рубль'],['Владелец','Марат Мнацаканян']])}</article><article class="product"><h2>Валютный счёт</h2>${facts([['Доступно',money(state.usd,'usd')],['Валюта','Доллар США'],['Расчётный курс','95 ₽ за доллар']])}</article></div><p class="section-note">Заморозка блокирует оплату картой внутри приложения. Счета и обмен валют остаются доступны. Лимит применяется к сумме карточных платежей за текущий день.</p>`}
function payments(){return heading('Переводы и платежи','Все повседневные задачи — в одном месте.')+`<div class="grid-3">${[['Перевод получателю','По имени получателя, между личными балансами.','↗','send'],['Между своими счетами','Рубли и доллары по курсу 95 ₽.','⇄','exchange'],['Мобильная связь','Пополнение телефона с рублёвой карты.','▯','mobile'],['ЖКХ и услуги','Коммунальные услуги и интернет.','⌂','bills'],['Оплата покупки','Покупка с выбранной карты.','▱','purchase'],['Пополнить баланс','Задать пополнение личного Wallet.','＋','add']].map(([name,sub,i,action])=>`<article class="product">${icon(i)}<h2>${name}</h2><p>${sub}</p><div class="gap">${btn('Продолжить',action)}</div></article>`).join('')}</div><p class="section-note">Все действия выполняются локально в вашей визуализации. Платежи и переводы в настоящие банки не отправляются.</p>`}
function deposits(){return heading('Вклады','Сбережения с понятными условиями.',btn('Открыть вклад','deposit','', 'solid'))+`<div class="grid-2">${state.deposits.map(d=>`<article class="product"><div class="row"><h2>${esc(d.name)}</h2><span class="tag">Открыт</span></div><strong class="value">${money(d.amount)}</strong><p>Ставка ${d.rate}% годовых · ${d.months} мес.</p>${facts([['Расчётный доход за срок',money(round(d.amount*d.rate/100*d.months/12))],['Дата открытия',new Date(d.opened).toLocaleDateString('ru-RU')],['Выплата процентов','В конце срока']])}<div class="gap">${btn('Закрыть вклад','close-deposit',`data-id="${d.id}"`)}</div></article>`).join('')||'<p class="empty-state">Открытых вкладов нет</p>'}</div><div class="section-heading"><h2>Условия накоплений</h2></div><div class="grid-3">${[[3,12],[6,14],[12,16]].map(([m,r])=>`<article class="product"><span class="caption">${m} месяцев</span><strong class="value">${r}%</strong><p>От 10 000 ₽ · без пополнения</p><div class="gap">${btn('Выбрать','deposit',`data-months="${m}"`)}</div></article>`).join('')}</div><p class="section-note">Ставки условные. Доход показан по простой формуле без капитализации. При досрочном закрытии возвращается только основная сумма; в конце срока доступны расчётные проценты.</p>`}
function investments(){return heading('Инвестиции','Ваш портфель и инструменты для его роста.')+`<div class="grid-2"><article class="product hero"><span class="caption">Стоимость портфеля</span><strong class="value">${money(investmentTotal())}</strong><p>3 инструмента · расчёты в рублях</p></article><article class="product"><h2>Доступно для покупки</h2><strong class="value">${money(state.rub)}</strong><p>Покупки списываются с рублёвого счёта. Выручка от продажи возвращается на него.</p></article></div><div class="section-heading"><h2>Инструменты</h2><span class="period">РАСЧЁТНЫЕ ЦЕНЫ</span></div><article class="product">${market.map(m=>`<div class="holding"><div class="holding-icon">${m.symbol}</div><div class="holding-info"><strong>${m.name}</strong><small>${m.category} · ${state.holdings[m.id]||0} шт.</small></div><div class="holding-price">${money((state.holdings[m.id]||0)*m.price)}<small>${fmt(m.price)} / шт.</small></div>${btn('Сделка','trade',`data-id="${m.id}"`)}</div>`).join('')}</article><p class="section-note">Инструменты вымышленные, котировки фиксированы. Сделки изменяют только локальный портфель; выхода на биржу нет.</p>`}
function assets(){const total=net();const items=[['Счета',liquid(),'#007aff'],['Вклады',depositTotal(),'#6b5ce7'],['Инвестиции',investmentTotal(),'#5ac8a8'],['Имущество',propertyTotal(),'#e8b85d']];return heading('Мои активы','Полная картина вашего капитала.',btn('Добавить актив','asset'))+`<div class="grid-2"><article class="product hero"><span class="caption">Чистый капитал</span><strong class="value">${money(total)}</strong><p>Все активы за вычетом кредитных обязательств.</p></article><article class="product"><h2>Структура активов</h2><div class="asset-bar">${items.map(([,n])=>`<span style="flex:${Math.max(0,n)}"></span>`).join('')}</div>${facts(items.map(([name,v,color])=>[`<i class="asset-dot" style="background:${color}"></i>${name}`,money(v)]))}</article></div><div class="grid-2 gap"><article class="product"><h2>Имущество</h2>${state.assets.map(a=>`<div class="holding"><div class="holding-info"><strong>${esc(a.name)}</strong><small>${esc(a.type)}</small></div><div class="holding-price">${money(a.value)}</div>${btn('Изменить','asset',`data-id="${a.id}"`)}</div>`).join('')||'<p class="empty-state">Добавьте свой первый актив</p>'}</article><article class="product"><h2>Финансовая цель</h2><strong class="value">${money(state.goal)}</strong><p>Текущий прогресс: ${Math.max(0,Math.min(100,Math.round(total/state.goal*100)))}%</p><progress class="gap" style="width:100%;accent-color:#007aff" max="100" value="${Math.max(0,Math.min(100,total/state.goal*100))}"></progress><div class="gap">${btn('Изменить цель','goal')}</div>${facts([['Кредитные обязательства',money(debtTotal())]])}</article></div><p class="section-note">Оценки имущества заданы вручную. Добавление имущества не пополняет счета. В чистом капитале каждый актив учтён один раз.</p>`}
const monthly=l=>{const r=l.rate/1200;return round(l.balance*r/(1-Math.pow(1+r,-l.months)))};
function loans(){return heading('Кредиты','Обязательства под вашим контролем.',btn('Рассчитать кредит','loan','', 'solid'))+`<div class="grid-2">${state.loans.filter(l=>l.balance>0).map(l=>`<article class="product"><div class="row"><h2>${esc(l.name)}</h2><span class="tag blue">Активен</span></div><span class="value">${money(l.balance)}</span><p>Остаток основного долга</p>${facts([['Ставка',l.rate+'% годовых'],['Срок расчёта',l.months+' мес.'],['Расчётный платёж',money(monthly(l))+' / мес.']])}<div class="gap">${btn('Погасить','repay',`data-id="${l.id}"`)}</div></article>`).join('')||'<div class="product"><h2>Всё погашено</h2><p>Активных кредитов нет.</p></div>'}<article class="product"><h2>Персональные условия</h2><span class="value">18%</span><p>От 10 000 до 10 000 000 ₽ · от 6 до 60 месяцев. Рассчитайте платёж перед добавлением кредита.</p><div class="gap">${btn('Калькулятор','loan')}</div></article></div><p class="section-note">Это локальная модель кредита. Сумма зачисляется на рублёвый баланс и учитывается как долг. Проценты автоматически не начисляются; калькулятор показывает аннуитетный платёж, а погашение уменьшает основной долг.</p>`}
const plans=[{name:'Защита дома',premium:25000,coverage:85000000,icon:'⌂'},{name:'В путешествии',premium:8000,coverage:5000000,icon:'✈'},{name:'Защита автомобиля',premium:120000,coverage:18000000,icon:'◇'}];
function insurance(){return heading('Страхование','Ваши планы под защитой.')+`<div class="section-heading"><h2>Мои программы</h2></div><div class="grid-2">${state.policies.map(p=>`<article class="product"><div class="row"><h2>${esc(p.name)}</h2><span class="tag">Добавлена</span></div>${facts([['Условное покрытие',money(p.coverage)],['Стоимость',money(p.premium)+' / год']])}<div class="gap">${btn('Подробнее','policy',`data-id="${p.id}"`)}</div></article>`).join('')||'<p class="empty-state">Программ пока нет</p>'}</div><div class="section-heading"><h2>Подобрать программу</h2></div><div class="grid-3">${plans.map((p,i)=>`<article class="product">${icon(p.icon)}<h2>${p.name}</h2><p>Покрытие до ${fmt(p.coverage)}</p><strong class="value">${fmt(p.premium)}</strong><p>за год</p><div class="gap">${btn(state.policies.some(x=>x.name===p.name)?'Уже добавлена':'Добавить программу','insure',`data-index="${i}" ${state.policies.some(x=>x.name===p.name)?'disabled':''}`)}</div></article>`).join('')}</div><p class="section-note">Личная визуализация страховых продуктов. Реальные полисы не выпускаются, страховое покрытие не действует.</p>`}
function history(){return heading('История операций','Всё движение средств в вашем Wallet.')+`<div class="toolbar"><input id="historySearch" type="search" placeholder="Найти операцию" aria-label="Поиск операций"><select id="historyFilter" aria-label="Тип операции"><option value="all">Все операции</option><option value="in">Поступления</option><option value="out">Списания</option></select></div><article class="product history-list" id="fullHistory">${historyHtml(state.history)}</article>`}
function settings(){return heading('Настройки','Ваш профиль и предпочтения.')+`<div class="grid-2"><article class="product"><h2>Личный профиль</h2>${facts([['Имя','Марат Мнацаканян'],['Обслуживание','Central Private'],['Основная валюта','Российский рубль'],['Хранение данных','Этот браузер']])}</article><article class="product"><h2>Ваш Wallet</h2><div class="settings-row row"><div><strong>Скрывать суммы</strong><small>На всех страницах приложения</small></div><button class="switch" role="switch" aria-label="Скрывать суммы" aria-checked="${state.hidden}" data-action="toggle-hidden"></button></div><div class="settings-row row"><div><strong>Уведомления о действиях</strong><small>Всплывающие сообщения в приложении</small></div><button class="switch" role="switch" aria-label="Уведомления" aria-checked="${state.notifications}" data-action="toggle-notifications"></button></div><div class="settings-row row"><div><strong>Сбросить данные</strong><small>Вернуть исходные продукты и балансы</small></div>${btn('Сбросить','reset','','danger')}</div></article></div><p class="section-note">Данные сохраняются в localStorage этого браузера. Синхронизации между устройствами и доступа к реальным банковским счетам нет.</p>`}
const pages={accounts,payments:referencePayments,deposits,investments,assets,loans,insurance,history,settings,city:cityPage,chat:chatPage,showcase:showcasePage,cashback:cashbackPage,plans:plansPage};
function render(){renderOverview();$('homeDashboard').innerHTML=referenceHome();updateBottomNav();$('overviewPage').hidden=route!=='overview';$('routePage').hidden=route==='overview';if(pages[route])$('routePage').innerHTML=pages[route]();document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`CENTRAL BANK — ${document.querySelector('[data-route="'+route+'"]')?.textContent.slice(1).trim()||'Обзор'}`;document.querySelectorAll('.card').forEach((c,i)=>c.classList.toggle('muted-card',Boolean(state.frozen[i%2?'usd':'rub'])))}
function navigate(){const requested=location.hash.slice(1)||'overview';route=Object.hasOwn(pages,requested)?requested:'overview';render();window.scrollTo(0,0)}
function input(label,id,value='',type='text',min,step){return `<label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" required ${type==='number'?`min="${min??0.01}" max="${MAX}" step="${step??0.01}"`: 'maxlength="80"'}>`}
function select(label,id,options){return `<label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select>`}
const amount=(value=10000,label='Сумма')=>input(label,'amount',value,'number'),curr=()=>select('Счёт','currency',[['rub','Рубли · ₽'],['usd','Доллары · $']]);
function open(kind,p={}){uiMode=null;mode=kind;params=p;$('error').textContent='';const title={edit:'Настроить балансы',add:'Пополнение',exchange:'Обмен валюты',reset:'Сбросить Wallet?',send:'Перевод получателю',mobile:'Мобильная связь',bills:'Оплата услуг',purchase:'Оплата покупки',deposit:'Открыть вклад','close-deposit':'Закрыть вклад',trade:'Сделка',asset:'Мой актив',goal:'Финансовая цель',loan:'Калькулятор кредита',repay:'Погашение кредита',insure:'Добавить программу',policy:'Условия программы',limit:'Лимит карты',freeze:'Управление картой'};
$('modalTitle').textContent=title[kind]||'Управление';let fields='',description='Изменения сохраняются в вашем личном Wallet.';
if(kind==='edit')fields=input('Рублёвый баланс','rub',state.rub,'number',0)+input('Долларовый баланс','usd',state.usd,'number',0);
if(kind==='add')fields=curr()+amount(1000000);
if(kind==='exchange'){fields=select('С какого счёта','currency',[['rub','Из рублей в доллары'],['usd','Из долларов в рубли']])+amount(9500)+'<div id="exchangePreview" class="payment-preview"></div>';description='Фиксированный расчётный курс: 1 USD = 95 ₽.'}
if(['send','mobile','bills','purchase'].includes(kind)){fields=curr()+input(({send:'Получатель',mobile:'Номер телефона',bills:'Услуга или поставщик',purchase:'Название покупки'})[kind],'recipient','',kind==='mobile'?'tel':'text')+amount();description=kind==='send'?'Локальная запись перевода. Отправки средств за пределы приложения нет.':'Списание с карты внутри личной визуализации.'}
if(kind==='deposit'){fields=input('Название вклада','name','Капитал Плюс')+amount(100000,'Сумма · ₽')+select('Срок и ставка','months',[[3,'3 месяца · 12%'],[6,'6 месяцев · 14%'],[12,'12 месяцев · 16%']]);description='Средства будут переведены с рублёвого счёта на вклад. Минимум 10 000 ₽.'}
if(kind==='close-deposit'){const d=state.deposits.find(x=>x.id===p.id);description=`На рублёвый счёт вернётся ${fmt(d.amount)}. При досрочном закрытии проценты не выплачиваются.`;fields='<p class="modal-help">После закрытия вклад исчезнет из активных продуктов.</p>'}
if(kind==='trade'){const m=market.find(x=>x.id===p.id);description=`${m.name} · ${fmt(m.price)} за единицу. В портфеле: ${state.holdings[m.id]||0} шт.`;fields=select('Операция','side',[['buy','Купить'],['sell','Продать']])+input('Количество единиц','quantity',1,'number',1,1)+'<div class="payment-preview" id="tradePreview"></div>'}
if(kind==='asset'){const a=state.assets.find(x=>x.id===p.id);fields=input('Название','name',a?.name||'')+select('Тип актива','assetType',[['Недвижимость','Недвижимость'],['Автомобиль','Автомобиль'],['Бизнес','Бизнес'],['Другое','Другое']])+amount(a?.value||1000000,'Оценка · ₽');description='Ручная оценка имущества. Балансы счетов не изменятся.'}
if(kind==='goal')fields=amount(state.goal,'Целевой капитал · ₽');
if(kind==='loan'){fields=amount(1000000,'Сумма кредита · ₽')+input('Срок · месяцев','months',36,'number',6,1)+'<div id="loanPreview" class="payment-preview"></div>';description='Условная ставка 18% годовых. После подтверждения сумма добавится на счёт и в обязательства.'}
if(kind==='repay'){const l=state.loans.find(x=>x.id===p.id);description=`Остаток долга: ${fmt(l.balance)}. Погашение с рублёвого счёта.`;fields=amount(l.balance)}
if(kind==='insure'){const plan=plans[Number(p.index)];description=`${plan.name}. Условное покрытие ${fmt(plan.coverage)}. Стоимость ${fmt(plan.premium)} за год спишется с рублёвого счёта.`;fields='<p class="modal-help">Программа добавляется только в личную визуализацию. Настоящий страховой полис не оформляется.</p>'}
if(kind==='policy'){const policy=state.policies.find(x=>x.id===p.id);description=policy.name;fields=facts([['Условное покрытие',fmt(policy.coverage)],['Стоимость за год',fmt(policy.premium)],['Статус','Личная визуализация']]);}
if(kind==='limit'){const c=p.currency;description='Максимальная сумма карточных платежей за календарный день.';fields=amount(state.limits[c],`Лимит · ${c==='rub'?'₽':'$'}`)}
if(kind==='freeze'){description=state.frozen[p.currency]?'Разморозить карту и снова разрешить локальные платежи?':'Заморозить карту? Карточные платежи будут заблокированы до разморозки.'}
if(kind==='reset')description='Вернутся исходные балансы, вклады, инвестиции и имущество. История операций будет удалена.';
$('modalDescription').textContent=description;$('fields').innerHTML=fields;$('form').querySelector('[type=submit]').textContent={reset:'Сбросить',freeze:state.frozen[p.currency]?'Разморозить':'Заморозить',policy:'Понятно','close-deposit':'Закрыть вклад',insure:'Добавить',loan:'Добавить кредит',trade:'Подтвердить сделку'}[kind]||'Подтвердить';
if(kind==='deposit'&&p.months)$('months').value=p.months;if(kind==='asset'&&p.id)$('assetType').value=state.assets.find(x=>x.id===p.id).type;
$('modal').showModal();updatePreview()}
function updatePreview(){if(mode==='exchange'&&$('exchangePreview')){const n=Number($('amount').value);$('exchangePreview').textContent='К получению: '+fmt($('currency').value==='rub'?round(n/RATE):round(n*RATE),$('currency').value==='rub'?'usd':'rub')}
if(mode==='trade'&&$('tradePreview')){$('tradePreview').textContent='Сумма сделки: '+fmt(Number($('quantity').value)*market.find(m=>m.id===params.id).price)}
if(mode==='loan'&&$('loanPreview')){const n=Number($('amount').value),months=Number($('months').value);$('months').max=60;$('amount').max=10000000;$('loanPreview').textContent=n>0&&months>=6&&months<=60?'Расчётный платёж: '+fmt(monthly({balance:n,rate:18,months}))+' / мес.':'Укажите сумму от 10 000 ₽ и срок от 6 до 60 месяцев.'}}
const value=id=>$(id).value.trim(),num=id=>Number($(id).value);
function requireAmount(n){if(!Number.isFinite(n)||n<=0||n>MAX)throw Error('Введите положительную сумму не больше 1 триллиона.');}
function debit(c,n,card=false){requireAmount(n);if(n>state[c])throw Error('На счёте недостаточно средств.');if(card){if(state.frozen[c])throw Error('Карта заморожена. Разморозьте её в разделе «Счета и карты».');const today=new Date().toDateString(),spent=state.history.filter(t=>t.category==='card'&&t.currency===c&&new Date(t.date).toDateString()===today).reduce((n,t)=>n+t.amount,0);if(spent+n>state.limits[c])throw Error('Превышен дневной лимит карты. Измените лимит в разделе «Счета и карты».');}state[c]=round(state[c]-n)}
function credit(c,n){requireAmount(n);if(state[c]+n>MAX)throw Error('Баланс не может превышать 1 триллион.');state[c]=round(state[c]+n)}
$('form').addEventListener('submit',e=>{e.preventDefault();const before=structuredClone(state);try{
if(mode==='reset'){state=defaults();state.templates=[];state.scheduled=[];state.cashback=['shops','home'];state.chat=[{role:'assistant',text:'Марат, здравствуйте! Чем помочь?'}];}
else if(mode==='edit'){for(const c of ['rub','usd']){const n=num(c);if(!Number.isFinite(n)||n<0||n>MAX)throw Error('Недопустимый баланс.');state[c]=round(n)}}
else if(mode==='add'){const c=value('currency'),n=num('amount');credit(c,n);record('Пополнение баланса',n,c,'topup','in')}
else if(mode==='exchange'){const c=value('currency'),other=c==='rub'?'usd':'rub',n=num('amount'),received=round(c==='rub'?n/RATE:n*RATE);if(received<0.01)throw Error('Сумма слишком мала для обмена.');debit(c,n);credit(other,received);record('Обмен валюты',n,c,'exchange');record('Получено при обмене',received,other,'exchange','in')}
else if(['send','mobile','bills','purchase'].includes(mode)){const c=value('currency'),n=num('amount'),recipient=value('recipient');if(!recipient)throw Error('Укажите получателя.');if(mode==='mobile'&&!/^\+?[\d\s()-]{7,22}$/.test(recipient))throw Error('Проверьте номер телефона.');debit(c,n,mode!=='send');if(params.planId)state.scheduled=state.scheduled.filter(s=>s.id!==params.planId);record(({send:'Перевод: ',mobile:'Связь: ',bills:'Услуги: ',purchase:'Покупка: '})[mode]+recipient,n,c,mode==='send'?'transfer':'card')}
else if(mode==='deposit'){const n=num('amount'),months=num('months'),name=value('name');if(n<10000)throw Error('Минимальная сумма — 10 000 ₽.');if(!name)throw Error('Введите название.');const rate=({3:12,6:14,12:16})[months];if(!rate)throw Error('Выберите срок.');debit('rub',n);state.deposits.push({id:uid(),name,amount:n,months,rate,opened:Date.now()});record('Открытие вклада: '+name,n,'rub','deposit')}
else if(mode==='close-deposit'){const d=state.deposits.find(x=>x.id===params.id),maturity=new Date(d.opened);maturity.setMonth(maturity.getMonth()+d.months);const payout=d.amount+(Date.now()>=maturity.getTime()?round(d.amount*d.rate/100*d.months/12):0);credit('rub',payout);state.deposits=state.deposits.filter(x=>x.id!==d.id);record('Закрытие вклада: '+d.name,payout,'rub','deposit','in')}
else if(mode==='trade'){const m=market.find(x=>x.id===params.id),q=num('quantity');if(!Number.isInteger(q)||q<1)throw Error('Укажите целое количество единиц.');const n=q*m.price;if(value('side')==='buy'){debit('rub',n);state.holdings[m.id]=(state.holdings[m.id]||0)+q;record('Покупка: '+m.name,n,'rub','investment')}else{if(q>(state.holdings[m.id]||0))throw Error('В портфеле недостаточно единиц.');credit('rub',n);state.holdings[m.id]-=q;record('Продажа: '+m.name,n,'rub','investment','in')}}
else if(mode==='asset'){const n=num('amount'),name=value('name');requireAmount(n);if(!name)throw Error('Введите название актива.');const asset={id:params.id||uid(),name,type:value('assetType'),value:n};if(params.id)state.assets=state.assets.map(a=>a.id===params.id?asset:a);else state.assets.push(asset)}
else if(mode==='goal'){const n=num('amount');requireAmount(n);state.goal=n}
else if(mode==='loan'){const n=num('amount'),months=num('months');if(n<10000||n>10000000||!Number.isInteger(months)||months<6||months>60)throw Error('Сумма от 10 000 до 10 000 000 ₽, срок от 6 до 60 месяцев.');credit('rub',n);state.loans.push({id:uid(),name:'Персональный кредит',balance:n,rate:18,months});record('Зачисление кредита',n,'rub','loan','in')}
else if(mode==='repay'){const l=state.loans.find(x=>x.id===params.id),n=num('amount');if(n>l.balance)throw Error('Сумма превышает остаток долга.');debit('rub',n);l.balance=round(l.balance-n);record('Погашение кредита',n,'rub','loan')}
else if(mode==='insure'){const p=plans[Number(params.index)];if(state.policies.some(x=>x.name===p.name))throw Error('Программа уже добавлена.');debit('rub',p.premium);state.policies.push({...p,id:uid()});record('Страхование: '+p.name,p.premium,'rub','insurance')}
else if(mode==='limit'){const n=num('amount');requireAmount(n);state.limits[params.currency]=n}
else if(mode==='freeze')state.frozen[params.currency]=!state.frozen[params.currency];
save();$('modal').close();notify(mode==='policy'?'Условия программы просмотрены':'Wallet обновлён');
}catch(err){state=before;$('error').textContent=err.message}});
$('form').addEventListener('input',updatePreview);$('form').addEventListener('change',updatePreview);$('cancel').onclick=()=>$('modal').close();
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;if(action==='toggle-hidden'){state.hidden=!state.hidden;save();return}if(action==='toggle-notifications'){state.notifications=!state.notifications;save();return}open(action,{...button.dataset})});
document.addEventListener('input',e=>{if(['historySearch','historyFilter'].includes(e.target.id))filterHistory()});document.addEventListener('change',e=>{if(e.target.id==='historyFilter')filterHistory()});
function filterHistory(){const term=$('historySearch').value.toLocaleLowerCase(),filter=$('historyFilter').value;$('fullHistory').innerHTML=historyHtml(state.history.filter(t=>(filter==='all'||t.direction===filter)&&t.title.toLocaleLowerCase().includes(term)))}
$('edit').onclick=()=>open('edit');$('add').onclick=()=>open('add');$('transfer').onclick=()=>open('exchange');$('reset').onclick=()=>open('reset');$('visibility').onclick=()=>{state.hidden=!state.hidden;save()};$('year').textContent=new Date().getFullYear();window.addEventListener('hashchange',navigate);

