const refPaths={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',gift:'<rect x="4" y="9" width="16" height="12" rx="2"/><path d="M3 9h18M12 9v12M12 9H8a3 3 0 1 1 3-3zm0 0h4a3 3 0 1 0-3-3z"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M3 12h17m-6-6 6 6-6 6"/>',scan:'<path d="M4 9V5a1 1 0 0 1 1-1h4m6 0h4a1 1 0 0 1 1 1v4m0 6v4a1 1 0 0 1-1 1h-4m-6 0H5a1 1 0 0 1-1-1v-4"/>',pay:'<path d="M9 7a10 10 0 0 1 0 10m4-13a16 16 0 0 1 0 16m4-19a23 23 0 0 1 0 22M4 10a4 4 0 0 1 0 4"/>',wallet:'<rect x="3" y="6" width="18" height="14" rx="3"/><path d="M3 8V5a2 2 0 0 1 2-2h12m-1 9h5v5h-5a2.5 2.5 0 0 1 0-5Z"/>',accounts:'<path d="M5 5h14M5 12h14M5 19h9" stroke-width="4"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',payments:'<circle cx="12" cy="12" r="8" stroke-width="4"/>',city:'<path d="M4 20V7h6v13M10 20V3h7v17m0-10h4v10M2 20h21M7 10h0m6-3h0m0 4h0m0 4h0"/>',chat:'<path d="M4 4h16v13H9l-5 4Z"/><path d="M8 8h8M8 12h6"/>',showcase:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',transfer:'<path d="M3 7h17m-5-5 5 5-5 5M21 17H4m5-5-5 5 5 5"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18m-14 5h4"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 19h4"/>',bill:'<path d="M5 3h11l4 4v14H5Z"/><path d="M15 3v5h5M9 12h7m-7 4h5"/>',game:'<path d="M7 7h10c2 0 5 11 3 12-2 1-4-3-6-3h-4c-2 0-4 4-6 3C2 18 5 7 7 7Z"/><path d="M6 11h5m-2-2v5m7-3h0m2 2h0"/>',down:'<path d="M12 3v17m-6-6 6 6 6-6"/>',shield:'<path d="M4 3h16v10c0 5-8 9-8 9s-8-4-8-9Z"/>',atm:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8v6H8Zm2 11h4"/>',save:'<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="12" cy="12" r="4"/><path d="M12 10v4m-2-2h4"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 13h18m-11 0v3h4v-3"/>',chart:'<path d="M3 20h18M5 16l5-6 4 3 6-9"/>'};
function ri(name){return `<svg class="ref-icon" viewBox="0 0 24 24" aria-hidden="true">${refPaths[name]||refPaths.wallet}</svg>`}
function uiButton(text,action,iconName='plus',extra=''){return `<button type="button" class="service-square" data-ui="${action}" ${extra}>${ri(iconName)}<span>${text}</span></button>`}
function serviceLink(text,routeName,iconName){return `<a class="service-square" href="#${routeName}">${ri(iconName)}<span>${text}</span></a>`}
function referenceHome(){const spend=state.history.filter(t=>t.direction==='out'&&t.category==='card'&&new Date(t.date).getMonth()===new Date().getMonth()&&new Date(t.date).getFullYear()===new Date().getFullYear()).reduce((n,t)=>n+t.amount*(t.currency==='usd'?RATE:1),0);
return `<div class="home-ident"><h1>Главная</h1><span class="desktop-brand">CENTRAL BANK</span></div><div class="home-top"><a class="home-avatar" href="#settings" aria-label="Профиль Марата">М</a><input class="home-search" id="serviceSearch" type="search" placeholder="Поиск" aria-label="Поиск по услугам"><button class="gift-button" data-ui="cashback" aria-label="Кэшбэк и бонусы">${ri('gift')}</button></div><div id="serviceResults" class="search-results"></div><div class="home-balance">Марат Мнацаканян · CENTRAL BANK <button data-action="toggle-hidden">${state.hidden?'Показать суммы':'Скрыть суммы'}</button></div>
<div class="tile-grid"><a class="bank-tile" href="#accounts"><div class="tile-top"><span class="mini-card"><span>CB</span><span class="mini-network"><i></i><i></i></span></span><span class="tile-badge">Mastercard</span></div><strong class="tile-amount">${money(state.rub)}</strong><span class="tile-name">Black<small>Рублёвый счёт · 2026</small></span></a><a class="bank-tile" href="#accounts"><div class="tile-top"><span class="mini-card silver"><b>VISA</b></span><span class="tile-badge">Visa</span></div><strong class="tile-amount">${money(state.usd,'usd')}</strong><span class="tile-name">Platinum<small>Долларовый счёт · 0001</small></span></a><a class="bank-tile" href="#deposits"><div class="tile-top"><span class="round-blue">${ri('wallet')}</span><span class="tile-badge">до 16%</span></div><strong class="tile-amount">${money(depositTotal())}</strong><span class="tile-name">Накопления</span></a><a class="bank-tile" href="#assets"><div class="tile-top"><span class="neutral-icon">${ri('accounts')}</span></div><strong class="tile-all">Основные<br>счета и активы</strong></a></div>
<div class="quick-row"><button class="round-action" data-action="add"><span class="action-circle">${ri('plus')}</span>Пополнить</button><button class="round-action" data-ui="scan"><span class="action-circle">${ri('scan')}</span>Сканировать</button><button class="round-action" data-action="send"><span class="action-circle">${ri('arrow')}</span>Перевести</button><button class="round-action" data-ui="pay"><span class="action-circle">${ri('pay')}</span>CB Pay</button></div>
<div class="home-widgets"><a href="#history" class="widget widget-link"><div class="row"><div><h2>Операции</h2><p>Траты за месяц ${money(spend)}</p></div><div class="operation-illustration" aria-hidden="true"><i>▯</i><i>▣</i><i>⇄</i></div></div></a><a href="#cashback" class="widget widget-link"><div class="row"><h2>Кэшбэк<br>и бонусы <span class="unread-dot">1</span></h2><div class="bonus-logos" aria-hidden="true"><span>＋</span><span>◉</span><span>%</span></div></div></a><a href="#investments" class="widget widget-link"><div class="row"><span class="round-blue">${ri('chart')}</span><div class="widget-title" style="flex:1"><strong>${money(investmentTotal())}</strong><p>Инвестиции</p></div></div></a>${state.dismissedOffer?'':`<div class="widget offer-banner"><button class="offer-close" data-ui="dismiss-offer" aria-label="Скрыть предложение">×</button><div><h2>Больше возможностей</h2><p>Соберите капитал<br>для больших планов</p><a href="#assets" class="tile-full-link" style="color:#b5ccff">Мои активы →</a></div><div class="offer-art" aria-hidden="true">${ri('chart')}</div></div>`}<a href="#loans" class="widget widget-link"><div class="row"><span class="round-blue">${ri('wallet')}</span><div class="widget-title" style="flex:1"><strong>Кредиты</strong><p>Деньги и ваши планы</p></div></div><div class="notice-pill">${debtTotal()>0?'Остаток долга '+money(debtTotal())+'. Управляйте погашением в разделе кредитов.':'Активных кредитов нет. Рассчитайте условия под ваши планы.'}</div></a><a href="#assets" class="widget widget-link"><div class="row"><span class="round-blue">${ri('briefcase')}</span><div class="widget-title" style="flex:1"><strong>${money(propertyTotal())}</strong><p>Имущество и бизнес</p></div></div></a><a href="#insurance" class="widget widget-link"><div class="row"><span class="round-blue">${ri('shield')}</span><div class="widget-title" style="flex:1"><strong>Под защитой</strong><p>${state.policies.length} программы страхования</p></div></div></a><a href="#showcase" class="widget widget-link"><div class="row"><div><h2>Все возможности</h2><p>Вклады, инвестиции и сервисы</p></div><span style="color:#428bf2">${ri('showcase')}</span></div></a></div>`}
function referencePayments(){const contacts=[['Р','Мой резерв'],['С','Семья'],['Д','Друг'],['П','Партнёр']];return `<div class="ref-page"><h1 class="ref-page-title">Платежи</h1><div class="template-row"><button class="template-add" data-ui="template">${ri('plus')}<strong>Добавить<br>шаблон</strong></button>${(state.templates||[]).map(t=>`<button class="template-saved" data-ui="use-template" data-id="${esc(t.id)}"><strong>${esc(t.name)}</strong><small>${money(t.amount,t.currency)}</small></button>`).join('')}</div><div class="ref-grid"><section class="ref-panel full"><h2>Предстоящие</h2><p>Планируйте траты и следите за ними здесь, чтобы ничего не пропускать</p><button class="planned-button" data-ui="schedule">Запланировать${state.scheduled.length?' · '+state.scheduled.length:''}</button></section><div class="small-pill-row full"><a class="small-pill" href="#plans">${ri('bill')}На оплату ${state.scheduled.length?`<span class="unread-dot">${state.scheduled.length}</span>`:''}</a><a class="small-pill" href="#plans">${ri('wallet')}Мои планы</a></div><section class="ref-panel full"><h2>Перевод по телефону</h2><input class="recipient-input" id="phoneRecipient" placeholder="Введите номер или имя" aria-label="Номер или имя получателя"><button class="recipient-button" data-ui="phone-send">Продолжить перевод</button><div class="contact-row">${contacts.map(([letter,name])=>`<button class="contact" data-ui="contact" data-name="${name}"><span class="contact-avatar">${letter}</span><span>${name}</span></button>`).join('')}</div></section><a class="yellow-banner full" href="#assets"><div><h2>Создайте дом мечты</h2><p>Поставьте цель и следите,<br>как растёт ваш капитал</p></div><div class="yellow-art" aria-hidden="true">${ri('home')}</div></a><section class="ref-panel"><div class="panel-title-row"><h2>Переводы</h2><a href="#accounts">Все</a></div><div class="service-slider"><button class="service-square" data-action="exchange">${ri('transfer')}<span>Между<br>счетами</span></button>${uiButton('Получателю','send','card')}${uiButton('В валюте','foreign','globe')}${uiButton('По имени','send','wallet')}</div></section><section class="ref-panel"><div class="panel-title-row"><h2>Платежи</h2><a href="#history">История</a></div><div class="service-slider"><button class="service-square" data-action="mobile">${ri('phone')}<span>Мобильная<br>связь</span></button><button class="service-square" data-action="bills">${ri('bill')}<span>ЖКХ</span></button>${uiButton('Игры','games','game')}${uiButton('Интернет','internet','globe')}</div></section><section class="ref-panel full"><h2>Действия</h2><div class="service-slider">${uiButton('Пополнить','add','down')}${uiButton('Снять наличные','withdraw','wallet')}${uiButton('CB Pay','pay','pay')}${uiButton('QR и реквизиты','scan','scan')}${serviceLink('Счета и карты','accounts','card')}</div></section></div><p class="ref-footnote">Платежи записываются только в личной визуализации. Внешние переводы и списания не выполняются.</p></div>`}
function cityPage(){return `<div class="ref-page"><h1 class="ref-page-title">Город</h1><div class="yellow-banner"><div><h2>Ваш город. Ваш ритм.</h2><p>Повседневные сервисы<br>в одном приложении</p></div><div class="yellow-art" aria-hidden="true">${ri('home')}</div></div><div class="ref-panel gap"><h2>Сервисы рядом</h2><div class="service-slider">${uiButton('Транспорт','transport','arrow')}${uiButton('Рестораны','restaurants','wallet')}${uiButton('Развлечения','games','game')}${uiButton('Путешествия','travel','globe')}</div></div><div class="ref-grid gap"><section class="ref-panel"><h2>Дом и услуги</h2><p>Коммунальные услуги, связь и интернет.</p><div class="gap"><button class="service-btn" data-action="bills">Оплатить услугу</button></div></section><a class="widget widget-link" href="#cashback"><h2>Больше за покупки</h2><p>Выберите категории кэшбэка.</p><div class="bonus-logos gap"><span>%</span><span>＋</span><span>◉</span></div></a></div><p class="ref-footnote">Сервисы доступны как локальные категории расходов. Бронирование, покупка билетов и заказы в сторонних сервисах не выполняются.</p></div>`}
function showcasePage(){return `<div class="ref-page"><div class="showcase-hero"><div class="showcase-art" aria-hidden="true">${heroArt()}</div><h1>Капитал для больших планов</h1><p>Счета, сбережения и персональные возможности CENTRAL BANK</p><button class="yellow-button" data-action="loan">Рассчитать кредит</button></div><div class="ref-panel"><div class="service-four"><a href="#settings"><span class="service-icon">${ri('shield')}</span>Безопасность</a><a href="#accounts"><span class="service-icon">${ri('card')}</span>Мои карты</a><a href="#history"><span class="service-icon">${ri('bill')}</span>Операции</a><a href="#payments"><span class="service-icon">${ri('showcase')}</span>Все сервисы</a></div></div><div class="showcase-list ref-stack"><a class="widget widget-link" href="#deposits"><div class="row"><div><h2>Копить</h2><p>Вклады и накопительные<br>продукты до 16% годовых</p></div><span class="round-blue">${ri('save')}</span></div></a><a class="widget widget-link" href="#investments"><div class="row"><div><h2>Инвестировать</h2><p>Фонды, облигации и золото</p></div><span class="round-blue">${ri('chart')}</span></div></a><a class="widget widget-link" href="#assets"><div class="row"><div><h2>Приумножать</h2><p>Имущество и финансовые цели</p></div><span class="round-blue">${ri('home')}</span></div></a><a class="widget widget-link" href="#insurance"><div class="row"><div><h2>Защищать</h2><p>Дом, автомобиль и путешествия</p></div><span class="round-blue">${ri('shield')}</span></div></a><a class="widget widget-link" href="#loans"><div class="row"><div><h2>Планировать</h2><p>Кредитный калькулятор<br>и управление долгом</p></div><span class="round-blue">${ri('wallet')}</span></div></a></div><p class="ref-footnote">Условия и продукты вымышленные. Все действия доступны для личной визуализации.</p></div>`}
function cashbackPage(){const categories=[['shops','Покупки','5%'],['travel','Путешествия','7%'],['home','Дом и услуги','3%'],['food','Рестораны','5%']];return `<div class="ref-page"><h1 class="ref-page-title">Кэшбэк и бонусы</h1><section class="ref-panel"><h2>Ваши категории</h2><p>Выберите до двух категорий для личного плана расходов.</p></section><div class="offer-categories gap">${categories.map(([id,name,rate])=>`<button class="cashback-option ${state.cashback.includes(id)?'selected':''}" data-ui="cashback-category" data-id="${id}" aria-pressed="${state.cashback.includes(id)}"><strong>${rate}</strong><span>${name}</span><small>${state.cashback.includes(id)?'Выбрано ✓':'Нажмите, чтобы выбрать'}</small></button>`).join('')}</div><p class="ref-footnote">Категории сохраняются в этом браузере. Настоящий кэшбэк не начисляется.</p></div>`}
function plansPage(){return `<div class="ref-page"><h1 class="ref-page-title">Предстоящие платежи</h1><div class="ref-stack">${state.scheduled.length?state.scheduled.map(s=>`<section class="ref-panel"><h2>${esc(s.name)}</h2><p>${esc(s.recipient)} · ${new Date(s.date+'T12:00:00').toLocaleDateString('ru-RU')}</p><div class="row gap"><strong style="font-size:23px">${money(s.amount,s.currency)}</strong><span class="tag blue">Запланирован</span></div><div class="row gap"><button class="service-btn" data-ui="pay-plan" data-id="${s.id}">Перейти к оплате</button><button class="service-btn danger" data-ui="remove-plan" data-id="${s.id}">Удалить</button></div></section>`).join(''):'<section class="ref-panel"><h2>Всё под контролем</h2><p>Пока нет запланированных платежей. Добавьте первый, чтобы сохранить сумму и дату.</p></section>'}<button class="planned-button" data-ui="schedule">Запланировать платёж</button></div><p class="ref-footnote">Это список ваших планов. Автоматического списания нет; оплату нужно подтвердить отдельно.</p></div>`}
function chatPage(){return `<div class="ref-page"><h1 class="ref-page-title">Чат<small>Локальный помощник CENTRAL BANK</small></h1><div class="chat-messages" id="chatMessages">${(state.chat||[]).map(m=>`<div class="chat-bubble ${m.role==='user'?'user':''}"><div class="chat-author">${m.role==='user'?'Вы':'Помощник CENTRAL'}</div>${esc(m.text)}</div>`).join('')}</div><div class="chat-suggestions"><button data-ui="chat-question" data-question="Как открыть вклад?">Открыть вклад</button><button data-ui="chat-question" data-question="Где мои карты?">Мои карты</button><button data-ui="chat-question" data-question="Как сделать перевод?">Перевести деньги</button></div><form id="chatForm" class="chat-form"><input id="chatInput" maxlength="500" placeholder="Написать сообщение" aria-label="Сообщение помощнику" required><button type="submit" aria-label="Отправить сообщение">${ri('arrow')}</button></form><p class="ref-footnote">Ответы из встроенной справки. Это не сотрудник банка, сообщения никуда не отправляются.</p></div>`}
function updateBottomNav(){const groups={overview:['overview','accounts','assets','history','settings','cashback'],payments:['payments','plans'],city:['city'],chat:['chat'],showcase:['showcase','deposits','investments','loans','insurance']};$('bottomNav').innerHTML=[['overview','Главная','home'],['payments','Платежи','payments'],['city','Город','city'],['chat','Чат','chat'],['showcase','Витрина','showcase']].map(([r,label,i])=>`<a href="#${r}" ${groups[r].includes(route)?'aria-current="page"':''}>${r==='overview'?'<span class="nav-logo"><b>C</b></span>':ri(i)}<span>${label}</span></a>`).join('')}
let uiMode=null;
function openUi(kind,params={}){uiMode={kind,...params};$('error').textContent='';$('modalTitle').textContent=({template:'Новый шаблон',schedule:'Запланировать платёж',scan:'Платёж по QR',withdraw:'Снятие наличных'})[kind];$('modalDescription').textContent=({template:'Сохраните получателя и сумму для быстрого повторения.',schedule:'Сохраните план. Автоматического списания не будет.',scan:'Введите текст получателя из QR-кода или реквизитов. Камера и отправка в банк не используются.',withdraw:'Локальная запись снятия с выбранного счёта. Выдача настоящих наличных не выполняется.'})[kind];let f='';if(['template','schedule'].includes(kind))f=input('Название','uiName','')+input('Получатель','uiRecipient','')+curr()+amount();if(kind==='schedule')f+=input('Дата','uiDate',new Date().toLocaleDateString('en-CA'),'date');if(kind==='scan')f=input('Получатель или текст из QR','uiRecipient','')+curr()+amount();if(kind==='withdraw')f=curr()+amount();$('fields').innerHTML=f;$('form').querySelector('[type=submit]').textContent=kind==='withdraw'?'Записать снятие':kind==='scan'?'Перейти к переводу':'Сохранить';if(kind==='schedule')$('uiDate').min=new Date().toLocaleDateString('en-CA');$('modal').showModal()}
function chatReply(question){const t=question.toLocaleLowerCase();if(/вклад|копить|накоп/.test(t))return 'Откройте «Витрина» → «Копить». Можно выбрать вклад на 3, 6 или 12 месяцев. Сумма переместится с рублёвого счёта на вклад.';if(/карт|лимит|замороз/.test(t))return 'Нажмите на карту Black или Platinum на главной. В разделе «Счета и карты» доступны заморозка, разморозка и дневные лимиты.';if(/перев|плат/.test(t))return 'В разделе «Платежи» выберите получателя и сумму. Для обмена рублей и долларов нажмите «Между счетами». Все операции локальные.';if(/кредит|долг/.test(t))return 'Откройте «Витрина» → «Планировать». Там есть калькулятор кредита и погашение основного долга.';if(/инвест|фонд|золот/.test(t))return 'Откройте «Витрина» → «Инвестировать». Можно покупать и продавать единицы трёх инструментов по фиксированным расчётным ценам.';return 'Я помогу разобраться в разделах CENTRAL BANK. Спросите про карты, переводы, вклады, инвестиции или кредиты. Это личная визуализация; настоящие банковские операции здесь не выполняются.'}
function sendChat(text){if(!text.trim())return;state.chat.push({role:'user',text:text.trim().slice(0,500)},{role:'assistant',text:chatReply(text)});state.chat=state.chat.slice(-40);save();$('chatInput')?.focus()}
function initReference(){state.templates=Array.isArray(state.templates)?state.templates:[];state.scheduled=Array.isArray(state.scheduled)?state.scheduled:[];state.cashback=Array.isArray(state.cashback)?state.cashback:['shops','home'];state.chat=Array.isArray(state.chat)?state.chat:[{role:'assistant',text:'Марат, здравствуйте! Я ваш локальный помощник. Подскажу, где найти карты, вклады, переводы и другие возможности CENTRAL BANK.'}];
const nav=document.querySelector('aside .nav');nav.insertAdjacentHTML('beforeend','<a data-route="city" href="#city"><span>⌂</span>Город</a><a data-route="chat" href="#chat"><span>◻</span>Чат</a><a data-route="showcase" href="#showcase"><span>▦</span>Витрина</a>');
document.addEventListener('input',e=>{if(e.target.id==='serviceSearch'){const q=e.target.value.toLocaleLowerCase().trim();const sections=[['accounts','Счета и карты'],['payments','Платежи и переводы'],['deposits','Вклады и накопления'],['investments','Инвестиции'],['assets','Активы и имущество'],['loans','Кредиты'],['insurance','Страхование'],['settings','Настройки и профиль'],['history','История операций'],['cashback','Кэшбэк и бонусы'],['showcase','Витрина'],['city','Город'],['chat','Чат']];const found=sections.filter(([,name])=>name.toLocaleLowerCase().includes(q));$('serviceResults').innerHTML=q?(found.length?found.map(([r,n])=>`<a class="search-result" href="#${r}">${n}</a>`).join(''):'<span class="search-result">Ничего не найдено</span>'):''}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-ui]');if(!b)return;const a=b.dataset.ui;if(['template','schedule','scan','withdraw'].includes(a)){openUi(a);return}if(a==='dismiss-offer'){state.dismissedOffer=true;save();return}if(a==='cashback'){location.hash='cashback';return}if(a==='cashback-category'){const id=b.dataset.id;if(state.cashback.includes(id))state.cashback=state.cashback.filter(x=>x!==id);else if(state.cashback.length<2)state.cashback.push(id);else{notify('Можно выбрать до двух категорий');return}save();return}if(a==='chat-question'){sendChat(b.dataset.question);return}if(a==='remove-plan'){state.scheduled=state.scheduled.filter(s=>s.id!==b.dataset.id);save();return}if(a==='use-template'||a==='pay-plan'){const item=(a==='use-template'?state.templates:state.scheduled).find(s=>s.id===b.dataset.id);open('send');$('recipient').value=item.recipient;$('currency').value=item.currency;$('amount').value=item.amount;if(a==='pay-plan')params.planId=item.id;return}if(a==='contact'||a==='phone-send'){const name=a==='contact'?b.dataset.name:$('phoneRecipient').value;open('send');$('recipient').value=name;return}if(a==='foreign'){open('send');$('currency').value='usd';return}if(a==='pay'){open('purchase');$('modalTitle').textContent='CB Pay';$('modalDescription').textContent='Выберите карту и укажите покупку для личной визуализации. Бесконтактная оплата через NFC не выполняется.';return}if(['games','internet','transport','restaurants','travel'].includes(a)){open('purchase');$('recipient').value=({games:'Игры и развлечения',internet:'Интернет',transport:'Транспорт',restaurants:'Ресторан',travel:'Путешествия'})[a];return}if(['send','add'].includes(a))open(a)});
$('form').addEventListener('submit',e=>{if(!uiMode)return;e.preventDefault();e.stopImmediatePropagation();const before=structuredClone(state);try{const n=num('amount'),currency=value('currency');requireAmount(n);if(uiMode.kind==='withdraw'){debit(currency,n);record('Снятие наличных',n,currency,'withdraw');uiMode=null;save();$('modal').close();notify('Запись сохранена');return}const recipient=value('uiRecipient');if(!recipient)throw Error('Введите получателя.');if(uiMode.kind==='scan'){uiMode=null;open('send');$('recipient').value=recipient;$('currency').value=currency;$('amount').value=n;return}const name=value('uiName');if(!name)throw Error('Введите название.');const item={id:uid(),name,recipient,amount:n,currency};if(uiMode.kind==='schedule'){item.date=value('uiDate');if(!/^\d{4}-\d{2}-\d{2}$/.test(item.date)||new Date(item.date+'T23:59:59')<new Date())throw Error('Выберите сегодняшнюю или будущую дату.');state.scheduled.push(item)}else state.templates.push(item);uiMode=null;save();$('modal').close();notify('Сохранено')}catch(error){state=before;$('error').textContent=error.message}},true);
document.addEventListener('submit',e=>{if(e.target.id==='chatForm'){e.preventDefault();sendChat($('chatInput').value)}})
}

initReference();navigate();
function heroArt(){return `<svg viewBox="0 0 300 170" width="270" height="165" aria-hidden="true"><defs><linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f4f3ee"/><stop offset=".45" stop-color="#dddeda"/><stop offset="1" stop-color="#a6aaa9"/></linearGradient><linearGradient id="golden" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff153"/><stop offset=".55" stop-color="#ffe02b"/><stop offset="1" stop-color="#dfab09"/></linearGradient><filter id="artshadow" x="-50%" y="-50%" width="200%" height="220%"><feDropShadow dx="3" dy="7" stdDeviation="4" flood-color="#3f4655" flood-opacity=".28"/></filter></defs><ellipse cx="155" cy="151" rx="113" ry="10" fill="#525b7022"/><g filter="url(#artshadow)"><path d="M133 24q0-18 20-18h70q17 0 19 18v112q-2 15-19 16h-70q-20-2-20-20Z" fill="#a2a7aa"/><rect x="125" y="3" width="110" height="146" rx="21" fill="url(#metal)" stroke="#f5f5ef" stroke-width="2" transform="rotate(9 180 75)"/><g fill="url(#golden)" stroke="#ffe84e" stroke-width="2" transform="rotate(9 180 75)"><circle cx="155" cy="39" r="13"/><circle cx="204" cy="112" r="13"/><path d="m145 112 57-86 13 9-57 86Z"/></g><path d="m35 99 43-38 43 31v54H96v-38L78 94l-21 18v34H35Z" fill="#d5ad0c"/><path d="m27 98 43-40 45 33-10 12-35-25-31 30v38H27Z" fill="url(#golden)"/><path d="M35 136h70v13H35Z" fill="#ffe238"/><ellipse cx="79" cy="153" rx="24" ry="9" fill="#d8d8ca" stroke="#f7f7ec" stroke-width="4"/><path d="m102 150 51-9 8 4-7 8-8-1-4 5-7-3-31 4" fill="url(#metal)" stroke="#f4f4e8" stroke-width="2"/></g></svg>`}
